import React from 'react';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import { useToast } from '../../../contexts/ToastContext';

const AcademyShareModal = ({ isOpen, onClose, course, type = 'course', data = null }) => {
    const { addToast } = useToast();
    if (!isOpen) return null;

    // Determine content based on type
    const item = data || course;
    const shareUrl = window.location?.href;

    let shareText = '';
    let title = '';
    let subtitle = '';

    if (type === 'badge') {
        title = 'Share Your Badge';
        subtitle = 'Show off your achievement';
        shareText = `I just earned the "${item?.name}" badge on LUC Academy! Join me and unlock your potential.`;
    } else if (type === 'certificate') {
        title = 'Share Certificate';
        subtitle = 'Professional Milestone';
        shareText = `I'm proud to certify my skills in "${item?.title}" from LUC Academy!`;
    } else {
        // Default to course
        title = 'Spread the Knowledge';
        subtitle = 'Share this course';
        shareText = `Elevate your potential with this course: ${course?.title} at LUC Academy!`;
    }

    const shareOptions = [
        {
            name: 'WhatsApp',
            icon: 'MessageCircle',
            color: 'bg-[#25D366]',
            action: () => {
                window.open(
                    `https://wa.me/?text=${encodeURIComponent(shareText + ' ' + shareUrl)}`,
                    '_blank'
                );
            }
        },
        {
            name: 'Facebook',
            icon: 'Facebook',
            color: 'bg-[#1877F2]',
            action: () => {
                window.open(
                    `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(shareUrl)}`,
                    '_blank'
                );
            }
        },
        {
            name: 'Twitter',
            icon: 'Twitter',
            color: 'bg-[#000000]', // X brand color
            action: () => {
                window.open(
                    `https://twitter.com/intent/tweet?text=${encodeURIComponent(shareText)}&url=${encodeURIComponent(shareUrl)}`,
                    '_blank'
                );
            }
        },
        {
            name: 'LinkedIn',
            icon: 'Linkedin',
            color: 'bg-[#0A66C2]',
            action: () => {
                window.open(
                    `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(shareUrl)}`,
                    '_blank'
                );
            }
        },
        {
            name: 'Email',
            icon: 'Mail',
            color: 'bg-primary/80',
            action: () => {
                window.location.href = `mailto:?subject=${encodeURIComponent(course?.title)}&body=${encodeURIComponent(shareText + '\n\n' + shareUrl)}`;
            }
        },
        {
            name: 'Copy Link',
            icon: 'Link',
            color: 'bg-secondary',
            action: () => {
                navigator.clipboard?.writeText(shareUrl);
                addToast('Course link copied to clipboard!', 'success');
            }
        }
    ];

    return (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in duration-300">
            <div
                className="bg-card border border-white/10 rounded-[2.5rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300"
                onClick={(e) => e.stopPropagation()}
            >
                <div className="p-6 border-b border-border flex items-center justify-between bg-primary/5">
                    <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-2xl bg-secondary/20 flex items-center justify-center text-secondary">
                            <Icon name="Share2" size={20} />
                        </div>
                        <div>
                            <h2 className="text-lg font-black text-primary italic leading-none mb-1">{title}</h2>
                            <p className="text-[10px] text-muted-foreground uppercase tracking-widest font-bold">{subtitle}</p>
                        </div>
                    </div>
                    <button
                        onClick={onClose}
                        className="w-8 h-8 rounded-full hover:bg-muted flex items-center justify-center transition-colors text-muted-foreground hover:text-primary"
                    >
                        <Icon name="X" size={18} />
                    </button>
                </div>

                <div className="p-8">
                    <div className="grid grid-cols-3 gap-4">
                        {shareOptions.map((option) => (
                            <button
                                key={option.name}
                                onClick={option.action}
                                className="flex flex-col items-center gap-3 p-4 rounded-3xl border border-border hover:border-secondary/30 hover:bg-secondary/5 transition-all group"
                            >
                                <div className={`w-12 h-12 rounded-2xl ${option.color} flex items-center justify-center text-white shadow-lg group-hover:scale-110 transition-transform`}>
                                    <Icon name={option.icon} size={20} />
                                </div>
                                <span className="text-[10px] font-black uppercase tracking-tighter text-muted-foreground group-hover:text-primary transition-colors">{option.name}</span>
                            </button>
                        ))}
                    </div>

                    <div className="mt-8 p-6 rounded-[2rem] bg-muted/30 border border-border/50 relative overflow-hidden">
                        <div className="absolute top-0 right-0 w-24 h-24 bg-secondary/5 blur-3xl rounded-full" />
                        <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground mb-3 opacity-50">Link</p>
                        <div className="flex items-center gap-2">
                            <input
                                type="text"
                                value={shareUrl}
                                readOnly
                                className="flex-1 px-4 py-2 text-xs bg-background border border-border rounded-xl text-primary font-medium focus:outline-none"
                            />
                            <Button
                                variant="primary"
                                size="sm"
                                className="rounded-xl h-9 italic font-black"
                                onClick={() => {
                                    navigator.clipboard?.writeText(shareUrl);
                                    addToast('Link copied!', 'success');
                                }}
                            >
                                COPY
                            </Button>
                        </div>
                    </div>
                </div>
            </div>
            {/* Click outside to close */}
            <div className="absolute inset-0 -z-10" onClick={onClose} />
        </div>
    );
};

export default AcademyShareModal;
