import React, { useState, useEffect } from 'react';
import { supabase } from '../../utils/supabaseClient';
import Icon from '../AppIcon';
import { detectContactSharing, CONTACT_GUARD_SHORT } from '../../utils/contactGuard';
import { useToast } from '../../contexts/ToastContext';

const SharedScratchpad = ({ roomId, isSolo }) => {
    const [content, setContent] = useState('');
    const [isSyncing, setIsSyncing] = useState(false);
    const { addToast } = useToast();

    useEffect(() => {
        if (isSolo) return;

        const channel = supabase.channel(`scratchpad_${roomId}`, {
            config: {
                broadcast: { self: false }
            }
        });

        channel
            .on('broadcast', { event: 'text_update' }, (payload) => {
                setContent(payload.payload.text);
                setIsSyncing(true);
                setTimeout(() => setIsSyncing(false), 500);
            })
            .subscribe();

        return () => {
            supabase.removeChannel(channel);
        };
    }, [roomId, isSolo]);

    const handleChange = (e) => {
        const newText = e.target.value;
        const guard = detectContactSharing(newText);
        if (guard.blocked) {
            addToast(CONTACT_GUARD_SHORT, 'error');
            return;
        }

        setContent(newText);

        if (!isSolo) {
            supabase.channel(`scratchpad_${roomId}`).send({
                type: 'broadcast',
                event: 'text_update',
                payload: { text: newText }
            });
        }
    };

    return (
        <div className="w-full h-full flex flex-col bg-slate-900 border-l border-white/10 relative">
            <div className="h-12 shrink-0 border-b border-white/10 px-4 flex items-center justify-between">
                <div className="flex items-center gap-2">
                    <Icon name="Edit3" size={14} className="text-primary" />
                    <span className="text-xs font-bold text-white uppercase tracking-wider">
                        {isSolo ? 'Personal Scratchpad' : 'Live Shared Scratchpad'}
                    </span>
                </div>
                {!isSolo && (
                    <div className="flex items-center gap-1.5">
                        <div className={`w-1.5 h-1.5 rounded-full ${isSyncing ? 'bg-emerald-500 animate-pulse' : 'bg-slate-600'}`} />
                        <span className="text-[10px] text-slate-400 font-medium">Real-time Sync</span>
                    </div>
                )}
            </div>
            <textarea
                value={content}
                onChange={handleChange}
                placeholder="Type code snippets, formulas, or notes here. No phone numbers, emails, or WhatsApp — stay on LUC."
                className="flex-1 w-full p-4 bg-transparent text-slate-300 text-sm font-mono outline-none resize-none placeholder:text-slate-600"
            />
        </div>
    );
};

export default SharedScratchpad;
