import React, { useState } from 'react';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import { cn } from '../../../utils/cn';

const LessonAssessment = ({ assessment, onPass, onFail, onBack }) => {
    const [selectedOption, setSelectedOption] = useState(null);
    const [isSubmitted, setIsSubmitted] = useState(false);
    const [isCorrect, setIsCorrect] = useState(false);

    const handleSubmit = () => {
        if (selectedOption === null) return;

        const correct = selectedOption === assessment.correctAnswer;
        setIsCorrect(correct);
        setIsSubmitted(true);

        if (correct) {
            setTimeout(() => onPass(), 1500);
        } else {
            // Provide visual feedback, but don't force a reset immediately
            // The user can click 'Retry' manually, or we could potentially 
            // auto-rewind after a longer delay if they stay stuck.
        }
    };

    const handleRetry = () => {
        setSelectedOption(null);
        setIsSubmitted(false);
    };

    return (
        <div className="bg-card/95 backdrop-blur-md border border-border rounded-[2rem] p-4 sm:p-6 w-full max-w-2xl mx-auto animate-in fade-in zoom-in duration-500 shadow-2xl max-h-full overflow-y-auto scrollbar-hide">
            <div className="flex items-center gap-3 mb-4">
                <div className="w-8 h-8 bg-secondary/10 rounded-xl flex items-center justify-center text-secondary shrink-0">
                    <Icon name="FileQuestion" size={20} />
                </div>
                <div>
                    <h3 className="text-lg font-black text-primary italic leading-none">Knowledge Check</h3>
                    <p className="text-[10px] text-muted-foreground">Answer to continue</p>
                </div>

            </div>

            <div className="space-y-4">
                <p className="text-base font-bold text-primary leading-tight">
                    {assessment.question}
                </p>

                <div className="grid gap-2">
                    {assessment.options.map((option, index) => (
                        <button
                            key={index}
                            disabled={isSubmitted}
                            onClick={() => setSelectedOption(index)}
                            className={cn(
                                "flex items-center gap-3 p-3 rounded-xl border-2 transition-all text-left group",
                                selectedOption === index
                                    ? "bg-secondary/10 border-secondary shadow-md"
                                    : "bg-muted/10 border-transparent hover:border-muted/50",
                                isSubmitted && index === assessment.correctAnswer && "bg-success/10 border-success text-success",
                                isSubmitted && selectedOption === index && index !== assessment.correctAnswer && "bg-destructive/10 border-destructive text-destructive"
                            )}
                        >
                            <div className={cn(
                                "w-6 h-6 rounded-full border-2 flex items-center justify-center shrink-0 text-xs font-bold transition-colors",
                                selectedOption === index
                                    ? "border-secondary bg-secondary text-white"
                                    : "border-muted-foreground/30 group-hover:border-muted-foreground/50"
                            )}>
                                {String.fromCharCode(65 + index)}
                            </div>
                            <span className={cn(
                                "font-medium text-sm transition-colors",
                                selectedOption === index ? "text-primary" : "text-primary/90"
                            )}>
                                {option}
                            </span>
                            {isSubmitted && index === assessment.correctAnswer && (
                                <Icon name="CheckCircle" size={18} className="ml-auto text-success" />
                            )}
                            {isSubmitted && selectedOption === index && index !== assessment.correctAnswer && (
                                <Icon name="XCircle" size={18} className="ml-auto text-destructive" />
                            )}
                        </button>
                    ))}
                </div>

                {!isSubmitted ? (
                    <Button
                        fullWidth
                        onClick={handleSubmit}
                        disabled={selectedOption === null}
                        iconName="ArrowRight"
                        iconPosition="right"
                        className="mt-4 font-black italic py-3"
                    >
                        SUBMIT ANSWER
                    </Button>
                ) : (
                    <div className="mt-4 animate-in slide-in-from-top-4 duration-300">
                        {isCorrect ? (
                            <div className="flex items-center gap-3 p-3 bg-success/10 border border-success/20 rounded-xl text-success">
                                <Icon name="ShieldCheck" size={20} />
                                <p className="font-bold text-sm">Correct! Continuing video...</p>
                            </div>
                        ) : (
                            <div className="space-y-3">
                                <div className="flex items-center gap-3 p-3 bg-destructive/10 border border-destructive/20 rounded-xl text-destructive">
                                    <Icon name="AlertCircle" size={20} />
                                    <p className="font-bold text-sm">Incorrect. Please try again.</p>
                                </div>
                                <div className="flex flex-col sm:flex-row gap-2">
                                    <Button
                                        variant="outline"
                                        fullWidth
                                        onClick={handleRetry}
                                        iconName="RotateCcw"
                                        className="py-3"
                                    >
                                        RETRY
                                    </Button>
                                    <Button
                                        variant="default"
                                        fullWidth
                                        onClick={() => onBack && onBack()}
                                        iconName="Rewind"
                                        className="py-3 bg-secondary hover:bg-secondary/90 border-transparent"
                                    >
                                        REWATCH
                                    </Button>
                                </div>
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
    );
};

export default LessonAssessment;
