import React, { useState } from 'react';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import { cn } from '../../../utils/cn';
import { detectContactSharing, CONTACT_GUARD_SHORT } from '../../../utils/contactGuard';

const CourseRating = ({ initialRating = 0, initialComment = '', onRate, onClose }) => {
    const [rating, setRating] = useState(initialRating);
    const [hover, setHover] = useState(0);
    const [comment, setComment] = useState(initialComment);
    const [isSubmitted, setIsSubmitted] = useState(false);
    const [guardError, setGuardError] = useState('');

    const handleSubmit = (e) => {
        e.preventDefault();
        if (rating === 0) return;

        const guard = detectContactSharing(comment);
        if (guard.blocked) {
            setGuardError(CONTACT_GUARD_SHORT);
            return;
        }

        setGuardError('');
        setIsSubmitted(true);
        setTimeout(() => {
            onRate({ rating, comment });
        }, 1500);
    };

    if (isSubmitted) {
        return (
            <div className="py-12 text-center animate-in fade-in duration-500">
                <div className="w-16 h-16 bg-success/10 text-success rounded-full flex items-center justify-center mx-auto mb-4">
                    <Icon name="Check" size={32} />
                </div>
                <h3 className="text-xl font-bold text-primary italic mb-2">Thank You!</h3>
                <p className="text-muted-foreground text-sm">Your feedback helps us make LUC Academy even better.</p>
            </div>
        );
    }

    return (
        <div className="p-2">
            <div className="text-center mb-6">
                <h3 className="text-xl font-black text-primary italic mb-1">Rate this Experience</h3>
                <p className="text-xs text-muted-foreground uppercase tracking-widest font-bold">How would you describe this content?</p>
            </div>

            <form onSubmit={handleSubmit} className="space-y-6">
                <div className="flex items-center justify-center gap-2">
                    {[1, 2, 3, 4, 5].map((star) => (
                        <button
                            key={star}
                            type="button"
                            className="p-1 transition-all hover:scale-125 focus:outline-none"
                            onClick={() => setRating(star)}
                            onMouseEnter={() => setHover(star)}
                            onMouseLeave={() => setHover(0)}
                        >
                            <Icon
                                name="Star"
                                size={40}
                                fill={(hover || rating) >= star ? "currentColor" : "none"}
                                className={cn(
                                    "transition-colors",
                                    (hover || rating) >= star ? "text-orange-400" : "text-muted/40"
                                )}
                            />
                        </button>
                    ))}
                </div>

                <div className="space-y-2">
                    <label className="text-xs font-bold text-muted-foreground">Share your thoughts (optional)</label>
                    <textarea
                        value={comment}
                        onChange={(e) => {
                            setComment(e.target.value);
                            if (guardError) setGuardError('');
                        }}
                        placeholder="What did you think of the instructor and the materials? (No phone, email, or WhatsApp)"
                        className="w-full bg-background text-primary border border-border rounded-2xl p-4 text-sm min-h-[100px] outline-none focus:ring-2 focus:ring-primary/20 transition-all"
                    />
                    {guardError && (
                        <p className="text-xs text-destructive font-medium">{guardError}</p>
                    )}
                    <p className="text-[10px] text-muted-foreground">
                        Contact sharing is blocked. Keep feedback on-platform.
                    </p>
                </div>

                <div className="flex gap-3">
                    <Button
                        fullWidth
                        type="submit"
                        disabled={rating === 0}
                        variant="default"
                        className="italic font-black py-4"
                    >
                        SUBMIT REVIEW
                    </Button>
                </div>
            </form>
        </div>
    );
};

export default CourseRating;
