import React, { useState } from 'react';
import Modal from '../../../components/ui/Modal';
import Button from '../../../components/ui/Button';
import Icon from '../../../components/AppIcon';
import Input from '../../../components/ui/Input';
import { useToast } from '../../../contexts/ToastContext';
import { detectContactSharing, validatePlatformWorkLink, CONTACT_GUARD_MESSAGE } from '../../../utils/contactGuard';

const ProofOfWorkCheckpoint = ({ isOpen, onClose, courseTitle, onSubmit }) => {
    const [projectUrl, setProjectUrl] = useState('');
    const [description, setDescription] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const { addToast } = useToast();

    const handleSubmit = async (e) => {
        e.preventDefault();

        const linkCheck = validatePlatformWorkLink(projectUrl);
        if (!linkCheck.ok) {
            addToast(linkCheck.message, "error");
            return;
        }

        const descGuard = detectContactSharing(description);
        if (descGuard.blocked) {
            addToast(CONTACT_GUARD_MESSAGE, "error");
            return;
        }

        setIsSubmitting(true);

        try {
            await new Promise(resolve => setTimeout(resolve, 1500));

            const finalUrl = projectUrl.startsWith('http') ? projectUrl : `https://${projectUrl}`;

            onSubmit({
                url: finalUrl,
                description,
                timestamp: new Date().toISOString()
            });

            addToast("Proof of Work verified! Portfolio updated.", "success");
        } catch (error) {
            addToast("Failed to submit Proof of Work.", "error");
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <Modal 
            isOpen={isOpen} 
            onClose={() => {}} // Force them to submit to complete the course!
            title="Application Checkpoint"
            size="lg"
        >
            <div className="p-6 md:p-8 space-y-6">
                <div className="text-center space-y-4 mb-8">
                    <div className="w-20 h-20 bg-brand-blue/10 rounded-full flex items-center justify-center mx-auto">
                        <Icon name="Briefcase" size={40} className="text-brand-blue" />
                    </div>
                    <h2 className="text-2xl font-black italic text-primary">Prove Your Knowledge.</h2>
                    <p className="text-muted-foreground text-sm max-w-md mx-auto">
                        At LUC Academy, we believe in <span className="font-bold text-primary">Application over IQ</span>. 
                        To complete <span className="font-bold italic">"{courseTitle}"</span> and earn your certificate, you must submit a live link proving you applied what you learned.
                    </p>
                </div>

                <form onSubmit={handleSubmit} className="space-y-6">
                    <div className="space-y-4">
                        <div className="space-y-2">
                            <label className="text-sm font-bold text-primary flex items-center gap-2">
                                <Icon name="Link" size={14} />
                                Project URL
                            </label>
                            <Input
                                placeholder="https://github.com/..., figma.com/..., docs.google.com/..."
                                value={projectUrl}
                                onChange={(e) => setProjectUrl(e.target.value)}
                                required
                                className="w-full"
                            />
                            <p className="text-xs text-muted-foreground">Submit a project link (GitHub, Figma, docs, etc.). WhatsApp, Telegram, and contact pages are not allowed.</p>
                        </div>

                        <div className="space-y-2">
                            <label className="text-sm font-bold text-primary flex items-center gap-2">
                                <Icon name="FileText" size={14} />
                                Brief Description (Optional)
                            </label>
                            <textarea
                                placeholder="What did you build using the concepts from this course? (No phone, email, or WhatsApp)"
                                value={description}
                                onChange={(e) => setDescription(e.target.value)}
                                className="w-full min-h-[100px] p-3 rounded-xl border border-input bg-background text-sm focus:ring-2 focus:ring-primary/20 outline-none resize-none"
                            />
                        </div>
                    </div>

                    <div className="bg-emerald-500/10 border border-emerald-500/20 rounded-xl p-4 flex items-start gap-3">
                        <Icon name="ShieldCheck" className="text-emerald-500 shrink-0 mt-0.5" size={18} />
                        <div>
                            <p className="text-sm font-bold text-emerald-600 dark:text-emerald-400">Public Portfolio Entry</p>
                            <p className="text-xs text-emerald-600/80 dark:text-emerald-400/80 mt-1">
                                This submission will be added to your public LUC Profile, building your verifiable track record for recruiters and scholarships.
                            </p>
                        </div>
                    </div>

                    <div className="flex justify-end gap-3 pt-4 border-t border-border">
                        <Button 
                            type="button" 
                            variant="ghost" 
                            onClick={onClose}
                            disabled={isSubmitting}
                        >
                            I'll do this later
                        </Button>
                        <Button 
                            type="submit" 
                            size="lg"
                            className="font-black italic shadow-xl shadow-primary/20"
                            disabled={!projectUrl || isSubmitting}
                            iconName={isSubmitting ? "RefreshCw" : "Upload"}
                            iconClassName={isSubmitting ? "animate-spin" : ""}
                        >
                            {isSubmitting ? "VERIFYING..." : "SUBMIT PROOF OF WORK"}
                        </Button>
                    </div>
                </form>
            </div>
        </Modal>
    );
};

export default ProofOfWorkCheckpoint;
